const items = $input.all();

function clean(value) {
  return String(value ?? '').trim();
}

function stripAccents(value) {
  return Array.from(clean(value).normalize('NFD'))
    .filter((char) => {
      const code = char.codePointAt(0);
      return code < 0x300 || code > 0x36f;
    })
    .join('')
    .toLowerCase();
}

function tokenize(text) {
  const normalized = stripAccents(text);
  const tokens = [];
  let current = '';

  for (const char of normalized) {
    const code = char.codePointAt(0);
    const isWordChar = (code >= 97 && code <= 122) || (code >= 48 && code <= 57);

    if (isWordChar) {
      current += char;
      continue;
    }

    if (current) {
      tokens.push(current);
      current = '';
    }
  }

  if (current) {
    tokens.push(current);
  }

  return Array.from(new Set(tokens.filter((token) => token.length > 2)));
}

function applyAliases(tokens) {
  const aliasMap = {
    usar: ['uso', 'utilizar', 'funcional', 'funcionalidade', 'operar'],
    uso: ['usar', 'utilizar', 'funcional', 'funcionalidade'],
    sistema: ['plataforma', 'painel', 'funcional', 'funcionalidade', 'uso'],
    cadastrar: ['cadastro', 'registrar', 'incluir', 'novo'],
    cadastro: ['cadastrar', 'registrar', 'incluir'],
    paciente: ['pacientes', 'cadastro paciente', 'cadastro de paciente', 'registro paciente'],
    pacientes: ['paciente', 'cadastro paciente', 'cadastro de paciente'],
    usuario: ['usuario', 'usuarios', 'acesso', 'perfil'],
    usuarios: ['usuario', 'acesso', 'perfil'],
    acesso: ['login', 'senha', 'perfil', 'usuario'],
    senha: ['acesso', 'login', 'usuario'],
    instalar: ['instalacao', 'implantar', 'implantacao', 'configurar'],
    instalacao: ['instalar', 'implantacao', 'configurar'],
    implantacao: ['implantar', 'instalacao', 'configurar'],
    implantar: ['instalacao', 'implantacao', 'configurar'],
    bug: ['erro', 'falha', 'inconsistencia', 'problema'],
    erro: ['bug', 'falha', 'problema'],
    exame: ['exames', 'laudo', 'laboratorio', 'resultado'],
    exames: ['exame', 'laudo', 'laboratorio'],
    faturamento: ['faturar', 'guia', 'convenio', 'cobranca'],
    treinamento: ['treinar', 'capacitacao', 'usuarios'],
    prontuario: ['prontuario', 'evolucao', 'atendimento'],
  };

  const expanded = [];

  for (const token of tokens) {
    expanded.push(token);
    const aliases = aliasMap[token] || [];

    for (const alias of aliases) {
      const normalizedAlias = stripAccents(alias).replace(/[^a-z0-9]+/g, '');
      if (normalizedAlias) {
        expanded.push(normalizedAlias);
      }
    }
  }

  return Array.from(new Set(expanded.filter(Boolean)));
}

function splitKnowledgeBase(text) {
  return clean(text)
    .split('\n---\n')
    .map((segment, index) => {
      const content = clean(segment);
      if (!content) return null;
      const lines = content.split(/\r?\n/);
      const title = clean(lines[0]).slice(0, 90) || ('Bloco ' + (index + 1));
      return { index: index + 1, title, content };
    })
    .filter(Boolean);
}

function scoreBlocks(query, blocks) {
  const tokens = applyAliases(tokenize(query));

  return blocks
    .map((block) => {
      const haystack = stripAccents((block.title || '') + ' ' + (block.content || ''));
      const titleHaystack = stripAccents(block.title || '');
      let score = 0;

      for (const token of tokens) {
        if (haystack.includes(token)) {
          score += titleHaystack.includes(token) ? 3 : 1;
        }
      }

      return { ...block, score };
    })
    .sort((a, b) => b.score - a.score);
}

function formatTimeline(timeline) {
  return (Array.isArray(timeline) ? timeline : [])
    .slice(-20)
    .map((entry) => {
      const direction = clean(entry.direction).toLowerCase() || 'message';
      const author = clean(entry.sender_name ?? entry.author ?? (direction === 'outbound' ? 'Agente' : 'Cliente')) || (direction === 'outbound' ? 'Agente' : 'Cliente');
      const body = clean(entry.body);
      return '- ' + author + ' (' + direction + '): ' + body;
    })
    .join('\n');
}

function formatKnowledge(blocks) {
  return (Array.isArray(blocks) ? blocks : [])
    .slice(0, 4)
    .map((block, index) => {
      const title = clean(block.title || ('Bloco ' + (index + 1)));
      const content = clean(block.content || '');
      return String(index + 1) + '. ' + title + '\n' + content;
    })
    .join('\n\n---\n\n');
}

function buildSummary(messageBody, timeline) {
  const parts = [];
  const recent = formatTimeline(timeline);

  if (messageBody) {
    parts.push('Cliente perguntou: "' + messageBody + '"');
  }

  if (recent) {
    parts.push('Histórico recente:\n' + recent);
  }

  return parts.join('\n');
}

function isGreetingOnly(messageBody) {
  const text = stripAccents(messageBody).replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!text) return true;

  const greetingWords = ['oi', 'ola', 'bom dia', 'boa tarde', 'boa noite', 'tudo bem', 'tudo certo', 'e ai', 'hello', 'olá'];
  const isShort = text.length <= 25;
  const hasGreeting = greetingWords.some((phrase) => text === phrase || text.startsWith(phrase + ' ') || text.includes(' ' + phrase + ' '));

  return hasGreeting && isShort;
}

function isLikelyQuestion(messageBody) {
  const text = stripAccents(messageBody).trim();
  if (!text) return false;

  const questionWords = ['como', 'quando', 'onde', 'porque', 'por que', 'qual', 'quais', 'preciso', 'quero', 'pode', 'poderia', 'deu erro', 'nao consigo', 'não consigo', 'me ajuda', 'ajuda'];
  const hasQuestionMark = messageBody.includes('?');
  const startsLikeQuestion = questionWords.some((word) => text.startsWith(word));
  const containsProblem = ['erro', 'falha', 'bug', 'problema', 'instalar', 'cadastrar', 'atualizar', 'faturamento', 'laudo', 'exame', 'usar', 'uso'].some((word) => text.includes(word));

  return hasQuestionMark || startsLikeQuestion || containsProblem;
}

function isBroadHelpRequest(messageBody) {
  const text = stripAccents(messageBody).replace(/\s+/g, ' ').trim();

  if (!text) {
    return true;
  }

  const phrases = [
    'pode me ajudar',
    'me ajuda',
    'preciso de ajuda',
    'quero ajuda',
    'como usar o sistema',
    'como funciona o sistema',
    'como usar',
    'como funciona',
    'me orienta',
    'me orientar',
    'me explique',
    'explica pra mim',
    'ajuda',
  ];

  return phrases.some((phrase) => text === phrase || text.startsWith(phrase + ' ') || text.includes(' ' + phrase + ' '));
}

function buildStepReply(match, messageBody) {

  const title = stripAccents(clean(match?.title || ''));
  const contentLines = clean(match?.content || '')
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);

  const stepLines = contentLines
    .filter((line) => {
      const first = line.charCodeAt(0);
      return (first >= 48 && first <= 57) || line.startsWith('-') || line.startsWith('•');
    })
    .map((line) => line.replace(/^\d+\.\s*/, '').replace(/^[-•]\s*/, '').trim())
    .filter(Boolean)
    .slice(0, 6);

  if (title.includes('cadastro de paciente') || title.includes('cadastro paciente') || stripAccents(match?.content || '').includes('cadastro de paciente')) {
    return [
      'Claro. Para cadastrar um paciente, siga este passo a passo:',
      '- Acesse o menu de pacientes ou cadastro.',
      '- Clique em novo cadastro ou incluir paciente.',
      '- Preencha nome, documento, data de nascimento, sexo, telefone e e-mail.',
      '- Se necessário, informe endereço, convênio, responsável e unidade.',
      '- Revise os campos obrigatórios e salve.',
      '',
      'Se quiser, eu posso detalhar um campo específico.'
    ].join('\n');
  }

  if (title.includes('suporte funcional') || title.includes('dúvida de uso') || title.includes('duvida de uso')) {
    return [
      'Claro — posso te orientar.',
      'Me diz qual parte do sistema você quer usar:',
      '- Pacientes',
      '- Atendimento',
      '- Faturamento',
      '- Exames ou laudos',
      '- Agenda',
      '',
      'Se preferir, já me fala o objetivo final que eu te passo o caminho.'
    ].join('\n');
  }

  if (title.includes('instalação') || title.includes('implantação')) {
    return [
      'Perfeito, vamos por partes.',
      'Para te orientar melhor na instalação ou implantação, preciso saber:',
      '- Se é teste, homologação ou produção',
      '- Qual módulo está em andamento',
      '- Em que etapa travou',
      '- Se apareceu alguma mensagem de erro',
      '',
      'Com isso eu consigo te passar o próximo passo certo.'
    ].join('\n');
  }

  if (title.includes('suporte técnico') || title.includes('bugs') || title.includes('erro')) {
    return [
      'Entendi. Vamos validar isso com calma.',
      'Me manda, por favor:',
      '- módulo e tela',
      '- horário do erro',
      '- mensagem exata exibida',
      '- se está acontecendo com todo mundo ou só com um usuário',
      '',
      'Assim eu consigo te orientar melhor ou encaminhar para análise técnica.'
    ].join('\n');
  }

  if (stepLines.length > 0) {
    return [
      'Claro. Pelo que encontrei na base, siga este passo a passo:',
      ...stepLines.map((line) => '- ' + line),
      '',
      'Se quiser, eu também posso detalhar um campo específico.'
    ].join('\n');
  }

  const excerpt = contentLines.slice(1, 4).join(' ').trim();
  return excerpt
    ? 'Claro. Pela base técnica, a orientação é: ' + excerpt + ' Se quiser, eu posso detalhar o próximo passo.'
    : 'Claro. Pela base técnica, consigo te orientar, mas preciso de um detalhe a mais para te passar o passo a passo certo.';
}

return items.map((item) => {
  const payload = item.json ?? {};
  const company = payload.company ?? {};
  const agent = payload.agent ?? {};
  const message = payload.message ?? {};
  const conversation = payload.conversation ?? {};
  const timeline = Array.isArray(payload.timeline) ? payload.timeline : [];
  const knowledgeBase = clean(payload.knowledge_base ?? '');
  const companyName = clean(company.trade_name ?? company.name ?? payload.company_name ?? 'a empresa') || 'a empresa';
  const agentName = clean(agent.name ?? 'Stark') || 'Stark';
  const assistantName = agentName;
  const messageBody = clean(message.body ?? payload.request?.message ?? '');
  const searchText = [messageBody, clean(payload.search_query ?? payload.searchQuery ?? ''), formatTimeline(timeline)].filter(Boolean).join(' ');

  const blocks = splitKnowledgeBase(knowledgeBase);
  const scoredBlocks = scoreBlocks(searchText, blocks);
  const knowledgeMatches = scoredBlocks.filter((block) => block.score > 0).slice(0, 3).map(({ score, ...block }) => block);
  const likelyQuestion = isLikelyQuestion(messageBody) || isLikelyQuestion(searchText);
  const greetingOnly = isGreetingOnly(messageBody) && !likelyQuestion;
  const broadHelpRequest = isBroadHelpRequest(messageBody) || isBroadHelpRequest(searchText);
  const canAnswer = knowledgeMatches.length > 0;
  const summary = buildSummary(messageBody, timeline);

const greetingReply = [
  'Oi! Tudo bem?',
  'Sou o Stark e estou por aqui para te ajudar com o sistema.',
  'Me conta o que você precisa e eu te guio.'
].join(' ');

const broadHelpReply = [
  'Claro. Posso te ajudar com cadastro, faturamento, exames, instalação, integração ou algum erro no sistema.',
  'Se quiser, me diz exatamente o que você está tentando fazer e eu sigo com você passo a passo.'
].join(' ');

const directReply = canAnswer
  ? buildStepReply(knowledgeMatches[0], messageBody)
  : '';

const handoffSummary = summary || 'Cliente pediu ajuda, mas não foi possível identificar uma resposta segura na base.';
const handoffReply = 'Vou encaminhar seu atendimento para a equipe dar continuidade.';

let finalReply = greetingReply;
let handoffToHuman = false;
let category = 'saudacao';
let notes = 'Mensagem de abertura; resposta curta e acolhedora.';

if (likelyQuestion) {
  if (canAnswer) {
    finalReply = directReply;
    category = 'suporte';
    notes = 'Resposta baseada na base técnica do cliente.';
  } else if (broadHelpRequest) {
    finalReply = broadHelpReply;
    category = 'abertura';
    notes = 'Pedido amplo de ajuda; resposta acolhedora com direcionamento.';
  } else {
    finalReply = handoffReply;
    handoffToHuman = true;
    category = 'handoff';
    notes = 'Sem base suficiente para responder com segurança.';
  }
} else if (greetingOnly) {
  finalReply = greetingReply;
  category = 'saudacao';
} else if (broadHelpRequest) {
  finalReply = broadHelpReply;
  category = 'abertura';
  notes = 'Pedido amplo de ajuda; resposta acolhedora com direcionamento.';
} else if (canAnswer) {
  finalReply = directReply;
  category = 'suporte';
  notes = 'Resposta baseada na base técnica do cliente.';
}

const finalConfidence = greetingOnly ? 0.9 : (canAnswer ? 0.96 : (broadHelpRequest ? 0.7 : (likelyQuestion ? 0.1 : 0.6)));


  return {
    json: {
      ...payload,
      company,
      agent,
      conversation,
      company_name: companyName,
      assistant_name: assistantName,
      knowledge_base: knowledgeBase,
      knowledge_matches: knowledgeMatches,
      timeline,
      conversation_summary: summary,
      response_mode: greetingOnly ? 'greeting' : (likelyQuestion ? 'analysis' : 'support'),
      final_reply: finalReply,
      final_handoff_to_human: handoffToHuman,
      final_confidence: finalConfidence,
      final_category: category,
      final_notes: notes,
      handoff_message: handoffReply,
      handoff_summary: handoffSummary,
      replied_to_message_id: Number(payload.message_id ?? payload.replied_to_message_id ?? 0) || null,
      external_message_id: String(payload.external_message_id ?? ('virtual-agent-response:' + (payload.message_id ?? Date.now()))),
      final_reply_debug: {
        greeting_only: greetingOnly,
        likely_question: likelyQuestion,
        can_answer: canAnswer,
        knowledge_titles: knowledgeMatches.map((match) => match.title),
      },
    },
  };
});

const items = $input.all();

function text(value) {
  return String(value ?? '').trim();
}

return items.map((item) => {
  const payload = item.json ?? {};
  const reply = text(payload.final_reply ?? payload.reply ?? payload.handoff_message);
  const handoffToHuman = Boolean(payload.final_handoff_to_human ?? payload.handoff_to_human ?? false);

  return {
    json: {
      ...payload,
      company_id: payload.company_id ?? payload.company?.id ?? null,
      conversation_id: payload.conversation_id ?? null,
      replied_to_message_id: Number(payload.replied_to_message_id ?? payload.message_id ?? 0) || null,
      external_message_id: text(payload.external_message_id ?? ('virtual-agent-response:' + (payload.replied_to_message_id ?? payload.message_id ?? Date.now()))),
      reply: reply,
      handoff_to_human: handoffToHuman,
      assistant_name: text(payload.assistant_name ?? payload.agent?.name ?? 'Stark') || 'Stark',
      confidence: Number(payload.final_confidence ?? payload.confidence ?? (handoffToHuman ? 0 : 0.95)),
      category: text(payload.final_category ?? payload.category ?? (handoffToHuman ? 'handoff' : 'suporte')) || 'suporte',
      notes: text(payload.final_notes ?? payload.notes ?? ''),
      summary: text(payload.handoff_summary ?? payload.conversation_summary ?? payload.summary ?? ''),
      handoff_message: text(payload.handoff_message ?? ''),
    },
  };
});
